function parseCategoryArgs(rest, known = Object.keys(DEFAULT_CATEGORIES)) {
  const vocabulary = [...new Set(known)];
  if (rest.length < 2) {
    return { error: `taste: category <text | id:...> <category>
categories: ${vocabulary.join(", ")}` };
  }
  const category = rest[rest.length - 1];
  const target = rest.slice(0, -1).join(" ").trim();
  if (!vocabulary.includes(category)) {
    return { error: `taste: unknown category "${category}"
categories: ${vocabulary.join(", ")}` };
  }
  return { target, category };
}

// src/hooks/injection.ts
function registerTasteInjection(pi, runtime) {
  registerTasteSnapshotRenderer(pi);
  pi.on("session_start", (_event, ctx) => {
    syncTasteSnapshot(pi, runtime, ctx.cwd);
  });
  pi.on("session_compact", (_event, ctx) => {
    syncTasteSnapshot(pi, runtime, ctx.cwd);
  });
  pi.on("before_agent_start", (event) => {
    const section = runtime.tasteSnapshot;
    if (!section) return;
    return { systemPrompt: `${event.systemPrompt}

${section}` };
  });
}

// src/runtime.ts
var Runtime = class {
  config = { ...DEFAULTS, classifier: { ...DEFAULTS.classifier } };
  configLoaded = false;
  /** True while a `/taste consolidate` run is in flight. */
  runInFlight = false;
  /** Current pipeline phase, for the command spinner. */
  phase;
  /** Rendered `<taste>` snapshot, frozen between compactions. */
  tasteSnapshot;
  /** Session-only worker model override set by `/taste model`; never persisted. */
  modelOverride;
  /** Set whenever a run finishes, so the next run can report what failed. */
  stageErrors = {};
  ensureConfig(cwd) {
    if (this.configLoaded) return;
    this.config = loadConfig(cwd);
    this.configLoaded = true;
  }
  /** Force the next `ensureConfig` to re-read settings (after `/taste enable`). */
  reloadConfig() {
    this.configLoaded = false;
  }
  recordStageError(stage, error) {
    const message = error instanceof Error ? error.message : String(error);
    this.stageErrors[stage] = message;
    return message;
  }
  clearStageErrors() {
    this.stageErrors = {};
  }
};

// src/index.ts
function taste(pi) {
  const runtime = new Runtime();
  registerTasteInjection(pi, runtime);
  registerTasteCommand(pi, runtime);
}
export {
  taste as default
};
